#include<bits/stdc++.h>
#define int long long
using namespace std;
vector<int>v[222222];
int f[222222],d[222222],vis[222222],di[222222];
int dp[555555][22];
void dfs(int p,int g,int fa){
	d[p]=g;
	dp[p][0]=fa;
	for(int i=1;i<=20;i++){
		dp[p][i]=dp[dp[p][i-1]][i-1];
	}
	for(int i=0;i<v[p].size();i++){
		if(v[p][i]!=fa){
			f[v[p][i]]=p;
			dfs(v[p][i],g+1,p);
		}
	}
}
int lca(int x,int y){
	if(d[x]<d[y]){
		swap(x,y);
	}
	for(int i=20;i>=0;i--){
		if(d[dp[x][i]]>=d[y]){
			x=dp[x][i];
		}
	}
	if(x==y){
		return d[x];
	}
	for(int i=20;i>=0;i--){
		if(dp[x][i]!=dp[y][i]){
			x=dp[x][i];
			y=dp[y][i];
		}
	} 
	return d[dp[x][0]];
}
int dis(int x,int y){
	return d[x]+d[y]-2*lca(x,y);
} 
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n,k,qq;
	cin>>n>>k>>qq;
	for(int i=1;i<n;i++){
		int x,y;
		cin>>x>>y;
		v[x].push_back(y);
		v[y].push_back(x);
	}
	dfs(1,1,0);
	queue<int>q;
	for(int i=1;i<=k;i++){
		int x;
		cin>>x;
		vis[x]=1;
		q.push(x);
	}
	while(!q.empty()){
		int x=q.front();
		q.pop();
		for(int i=0;i<v[x].size();i++){
			if(vis[v[x][i]]==0){
				q.push(v[x][i]);
				vis[v[x][i]]=1;
				di[v[x][i]]=di[x]+1;
			}
		}
	}
	while(qq--){
		int x,y;
		cin>>x>>y;
		if(k==0){
			cout<<dis(x,y)<<endl;
			continue;
		}
		cout<<min(dis(x,y),di[x]+di[y])<<endl;
	}
    return 0;
}
